const supaConfig=window.AB_CARRENT_SUPABASE||{}, supabaseConfigured=Boolean(supaConfig.url&&supaConfig.publishableKey), onlineMode=Boolean(supabaseConfigured&&window.supabase?.createClient), supabaseClient=onlineMode?window.supabase.createClient(supaConfig.url,supaConfig.publishableKey):null;
let db; if(onlineMode) db={cars:[],customers:[],bookings:[],expenses:[],quotes:[]}; else {try{const saved=JSON.parse(localStorage.getItem(KEY))||seed();db={...saved,quotes:saved.quotes||[]};db.bookings=db.bookings.map(b=>({receiptPrintedAt:null,taxInvoicePrintedAt:null,insurance:'',insuranceCoverage:0,extraCharges:[],...b}));db.customers=db.customers.map(c=>({taxType:'individual',line:'',taxName:'',taxId:c.license||'',taxAddress:c.address||'',province:'',district:'',subdistrict:'',postalCode:'',...c}));db.expenses=db.expenses.map(x=>({carId:'',...x}))}catch{db={...seed(),quotes:[]}}}
