const car=id=>db.cars.find(x=>x.id===id), customer=id=>db.customers.find(x=>x.id===id), dateFmt=s=>s?new Date(s.length===10?s+'T00:00':s).toLocaleDateString('th-TH',{day:'numeric',month:'short',year:'2-digit'}):'—', timeFmt=s=>s?new Date(s).toLocaleTimeString('th-TH',{hour:'2-digit',minute:'2-digit'}):'—', dtFmt=s=>`${dateFmt(s)} · ${timeFmt(s)}`;
