function availableCarsToday(){const start=new Date(`${todayISO()}T00:00`),end=new Date(start);end.setDate(end.getDate()+1);return db.cars.filter(c=>c.available&&!db.bookings.some(b=>b.carId===c.id&&!['cancelled','completed'].includes(b.status)&&new Date(b.start)<end&&new Date(b.end)>start))}
function renderAvailableToday(){const cars=availableCarsToday();$('#available-today-count').textContent=`${cars.length} คัน`;$('#available-today').innerHTML=cars.length?cars.map(c=>`<article class="available-car"><div class="available-car-photo">${c.image?`<img src="${esc(c.image)}" alt="${esc(c.name)}">`:`<span>${esc(c.icon||'🚘')}</span>`}</div><div class="available-car-info"><b>${esc(c.name)}</b><small>${esc(c.plate)} · ${c.seats} ที่นั่ง</small><strong>${money(c.price)} <small>/ วัน</small></strong></div></article>`).join(''):'<div class="available-empty">วันนี้ไม่มีรถว่างตลอดวัน เพิ่มช่วงเวลาจองใหม่เมื่อมีรถพร้อม</div>'}
function render(){renderDashboard();renderBookings();renderFleet();renderCustomers();renderFinance();$('#booking-count').textContent=db.bookings.filter(b=>!['completed','cancelled'].includes(b.status)).length;const free=availableCarsToday();$('#stat-available').textContent=free.length;$('#fleet-progress').style.width=(db.cars.length?free.length/db.cars.length*100:0)+'%';renderAvailableToday();const list=db.cars.filter(c=>carFilter==='all'||(carFilter==='available'?c.available:!c.available));$$('#car-grid .car-card').forEach((card,i)=>{const c=list[i];if(c?.image){const holder=card.querySelector('.car-visual span');if(holder)holder.innerHTML=`<img src="${esc(c.image)}" alt="${esc(c.name)}">`}})}
function compressCarPhoto(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(new Error('อ่านไฟล์รูปไม่สำเร็จ'));reader.onload=()=>{const img=new Image();img.onerror=()=>reject(new Error('ไฟล์รูปไม่ถูกต้อง'));img.onload=()=>{const scale=Math.min(1,1200/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',.76))};img.src=reader.result};reader.readAsDataURL(file)})}
function carForm(id=''){let old=id?car(id):null,image=old?.image||'';let m=openModal(old?'แก้ไขข้อมูลรถ':'เพิ่มรถยนต์','กำหนดข้อมูลรถ ราคา และรูปภาพ',`<form id="car-form"><div class="form-grid"><div class="field full"><label>ยี่ห้อและรุ่น *</label><input name="name" required value="${esc(old?.name||'')}" placeholder="เช่น Toyota Yaris Ativ"></div><div class="field full"><label>รูปรถ</label><input id="car-image" type="file" accept="image/*"><small class="photo-help">เลือกรูปจากอุปกรณ์ ระบบจะย่อรูปให้เหมาะกับการจัดเก็บ</small><img id="car-image-preview" class="car-photo-preview ${image?'':'hidden'}" src="${esc(image)}" alt="ตัวอย่างรูปรถ"></div><div class="field"><label>ทะเบียนรถ *</label><input name="plate" required value="${esc(old?.plate||'')}" placeholder="กข 1234 นครศรีฯ"></div><div class="field"><label>ประเภทรถ</label><select name="type">${['รถเก๋ง','SUV','รถกระบะ','รถตู้','อื่นๆ'].map(x=>`<option ${old?.type===x?'selected':''}>${x}</option>`)}</select></div><div class="field"><label>ราคาเช่าต่อวัน (บาท) *</label><input name="price" type="number" min="1" required value="${old?.price||''}"></div><div class="field"><label>จำนวนที่นั่ง</label><input name="seats" type="number" min="1" value="${old?.seats||5}"></div><div class="field"><label>เกียร์</label><select name="transmission"><option ${old?.transmission==='อัตโนมัติ'?'selected':''}>อัตโนมัติ</option><option ${old?.transmission==='ธรรมดา'?'selected':''}>ธรรมดา</option></select></div><div class="field"><label>เชื้อเพลิง</label><select name="fuel"><option>เบนซิน</option><option ${old?.fuel==='ดีเซล'?'selected':''}>ดีเซล</option><option ${old?.fuel==='ไฮบริด'?'selected':''}>ไฮบริด</option><option>ไฟฟ้า</option></select></div><div class="field"><label>สีรถ</label><input name="color" value="${esc(old?.color||'')}"></div><div class="field"><label>สถานะ</label><select name="available"><option value="true">พร้อมให้เช่า</option><option value="false" ${old?.available===false?'selected':''}>ไม่พร้อมให้เช่า</option></select></div></div><div class="form-actions"><button type="button" class="secondary-button cancel-modal">ยกเลิก</button><button class="primary-button">บันทึกข้อมูล</button></div></form>`);$('.cancel-modal').onclick=closeModal;$('#car-image').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;if(!file.type.startsWith('image/'))return toast('กรุณาเลือกไฟล์รูปภาพ');try{image=await compressCarPhoto(file);$('#car-image-preview').src=image;$('#car-image-preview').classList.remove('hidden')}catch{toast('ไม่สามารถเปิดไฟล์รูปนี้ได้')}};$('#car-form').onsubmit=e=>{e.preventDefault();let x=Object.fromEntries(new FormData(e.target));let c={...(old||{}),id:old?.id||'CAR-'+Date.now().toString().slice(-6),...x,price:Number(x.price),seats:Number(x.seats),available:x.available==='true',image,icon:old?.icon||({SUV:'🚙','รถกระบะ':'🛻','รถตู้':'🚐'}[x.type]||'🚘')};old?Object.assign(old,c):db.cars.push(c);persist();closeModal();toast(old?'บันทึกการแก้ไขแล้ว':'เพิ่มรถยนต์แล้ว')}}
const deepCopy=value=>JSON.parse(JSON.stringify(value));
const localDateTime=value=>{const d=new Date(value);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}T${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`};
