const bookingToDb=b=>({id:b.id,customer_id:b.customerId,car_id:b.carId,pickup_at:new Date(b.start).toISOString(),return_at:new Date(b.end).toISOString(),rental_days:b.days,daily_rate_snapshot:car(b.carId)?.price||0,total:b.total,deposit:b.deposit||0,payment_method:b.payment||'โอนเงิน',paid:Boolean(b.paid),status:b.status,insurance_name:b.insurance||null,insurance_coverage:b.insuranceCoverage||0,extra_charges:b.extraCharges||[],receipt_printed_at:b.receiptPrintedAt||null,tax_invoice_printed_at:b.taxInvoicePrintedAt||null,quote_id:b.quoteId||null,created_at:new Date(`${b.created||todayISO()}T12:00`).toISOString()});
