async function requireSupabaseResult(query){const {data,error}=await query;if(error)throw error;return data}
async function uploadCarPhoto(carRecord){if(!carRecord.image?.startsWith('data:'))return;const blob=await (await fetch(carRecord.image)).blob(),path=`${carRecord.id}/${Date.now()}-${Math.random().toString(36).slice(2)}.jpg`;const {error}=await supabaseClient.storage.from('car-photos').upload(path,blob,{contentType:'image/jpeg',upsert:false});if(error)throw error;carRecord.image=supabaseClient.storage.from('car-photos').getPublicUrl(path).data.publicUrl}
async function uploadCustomerDocuments(c){for(const key of ['idDocument','licenseDocument']){const data=c[key+'Data'];if(!data?.startsWith('data:'))continue;const blob=await(await fetch(data)).blob(),path=`${c.id}/${key}-${Date.now()}-${Math.random().toString(36).slice(2)}.pdf`,{error}=await supabaseClient.storage.from('customer-documents').upload(path,blob,{contentType:'application/pdf',upsert:false});if(error)throw error;c[key+'Path']=path;c[key+'Data']=''}}
const quoteFromDb=r=>({id:r.id,customerId:r.customer_id,carId:r.car_id,start:localDateTime(r.pickup_at),end:localDateTime(r.return_at),days:r.rental_days,total:Number(r.total),deposit:Number(r.deposit),insurance:r.insurance_name||'',insuranceCoverage:Number(r.insurance_coverage)||0,extraCharges:r.extra_charges||[],status:r.status,created:localDateStamp(r.created_at)});
const quoteToDb=q=>({id:q.id,customer_id:q.customerId,car_id:q.carId,pickup_at:new Date(q.start).toISOString(),return_at:new Date(q.end).toISOString(),rental_days:q.days,daily_rate_snapshot:car(q.carId)?.price||0,total:q.total,deposit:q.deposit||0,insurance_name:q.insurance||null,insurance_coverage:q.insuranceCoverage||0,extra_charges:q.extraCharges||[],status:q.status,created_at:new Date(`${q.created||todayISO()}T12:00`).toISOString()});
async function syncRemoteState(){if(!syncedState)return;const target=deepCopy(db),specs=[{key:'cars',table:'cars',to:carToDb},{key:'customers',table:'customers',to:customerToDb},{key:'bookings',table:'bookings',to:bookingToDb},{key:'expenses',table:'expenses',to:expenseToDb},{key:'quotes',table:'quotes',to:quoteToDb}];for(const spec of specs){const before=new Map((syncedState[spec.key]||[]).map(x=>[x.id,JSON.stringify(x)])),changed=target[spec.key].filter(x=>before.get(x.id)!==JSON.stringify(x));if(spec.key==='cars')for(const c of changed)await uploadCarPhoto(c);if(spec.key==='customers')for(const c of changed)await uploadCustomerDocuments(c);if(changed.length)await requireSupabaseResult(supabaseClient.from(spec.table).upsert(changed.map(spec.to)));}for(const spec of [...specs].reverse()){const now=new Set(target[spec.key].map(x=>x.id)),deleted=(syncedState[spec.key]||[]).filter(x=>!now.has(x.id)).map(x=>x.id);if(deleted.length)await requireSupabaseResult(supabaseClient.from(spec.table).delete().in('id',deleted));}for(const c of target.customers){const live=customer(c.id);if(live){for(const key of ['idDocument','licenseDocument'])if(live[key+'Data']&&c[key+'Path'])live[key+'Data']=''}}for(const savedCar of target.cars){const liveCar=car(savedCar.id);if(liveCar&&liveCar.image?.startsWith('data:')&&savedCar.image!==liveCar.image)liveCar.image=savedCar.image}syncedState=deepCopy(target)}
function persist(){if(!onlineMode){persistLocal();return}render();remoteSaveQueue=remoteSaveQueue.then(syncRemoteState).catch(error=>{const message=error?.code==='23P01'?'รถคันนี้ถูกจองทับช่วงเวลาโดยรายการอื่นแล้ว':(error?.message||'บันทึกฐานข้อมูลไม่สำเร็จ');db=deepCopy(syncedState||db);render();toast(message);console.error('AB CARRENT Supabase save:',error)});return remoteSaveQueue}
function showLogin(message=''){const screen=$('#auth-screen');screen.classList.remove('hidden');$('.sidebar').classList.add('hidden');$('.main').classList.add('hidden');$('#auth-error').textContent=message;$('#logout-button').classList.add('hidden')}
async function startRemoteSession(user){try{const admin=await requireSupabaseResult(supabaseClient.from('ab_admins').select('user_id,display_name').eq('user_id',user.id).maybeSingle());if(!admin){await supabaseClient.auth.signOut();showLogin('บัญชีนี้ยังไม่ได้รับสิทธิ์ผู้ดูแลระบบ');return}activeAdmin=admin;const [cars,customers,bookings,expenses,quotes]=await Promise.all([requireSupabaseResult(supabaseClient.from('cars').select('*').order('name')),requireSupabaseResult(supabaseClient.from('customers').select('*').order('name')),requireSupabaseResult(supabaseClient.from('bookings').select('*').order('created_at',{ascending:false})),requireSupabaseResult(supabaseClient.from('expenses').select('*').order('expense_date',{ascending:false})),requireSupabaseResult(supabaseClient.from('quotes').select('*').order('created_at',{ascending:false}))]);db={cars:cars.map(carFromDb),customers:customers.map(customerFromDb),bookings:bookings.map(bookingFromDb),expenses:expenses.map(expenseFromDb),quotes:quotes.map(quoteFromDb)};syncedState=deepCopy(db);$('#auth-screen').classList.add('hidden');$('.sidebar').classList.remove('hidden');$('.main').classList.remove('hidden');$('#logout-button').classList.remove('hidden');$('#profile-name').textContent=admin.display_name||user.email||'ผู้ดูแลระบบ';$('#storage-mode').textContent='ข้อมูลซิงก์ผ่าน Supabase';render()}catch(error){console.error('AB CARRENT Supabase load:',error);showLogin('เชื่อมฐานข้อมูลไม่สำเร็จ กรุณารัน migration ล่าสุดและตรวจสอบ RLS')}}
async function initializeApp(){if(supabaseConfigured&&!onlineMode){showLogin('โหลด Supabase client ไม่สำเร็จ กรุณารีเฟรชหน้าเว็บเมื่อเชื่อมต่ออินเทอร์เน็ต');return}if(!onlineMode){render();return}$('#login-form').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));$('#auth-error').textContent='กำลังเข้าสู่ระบบ…';const {data:result,error}=await supabaseClient.auth.signInWithPassword({email:data.email,password:data.password});if(error){$('#auth-error').textContent='อีเมลหรือรหัสผ่านไม่ถูกต้อง หรือยังตั้งค่าฐานข้อมูลไม่ครบ';return}await startRemoteSession(result.user)};$('#logout-button').onclick=async()=>{await supabaseClient.auth.signOut();showLogin()};const {data,error}=await supabaseClient.auth.getSession();if(error){showLogin('เชื่อมต่อ Supabase ไม่สำเร็จ');return}if(data.session)await startRemoteSession(data.session.user);else showLogin()}
function deleteCar(id){if(db.bookings.some(b=>b.carId===id))return toast('ลบรถไม่ได้ เพราะมีประวัติรายการเช่าอยู่');if(confirm('ยืนยันการลบรถคันนี้?')){db.cars=db.cars.filter(c=>c.id!==id);persist();toast('ลบรถออกจากระบบแล้ว')}}
// Navigation and controls
$$('.nav-item').forEach(x=>x.onclick=()=>show(x.dataset.view));$$('[data-goto]').forEach(x=>x.onclick=()=>show(x.dataset.goto));$('#quick-book').onclick=$('#new-booking').onclick=()=>bookingForm();$('#new-quote').onclick=quoteForm;$('#add-car').onclick=()=>carForm();$('#add-customer').onclick=()=>customerForm();$('#add-expense').onclick=expenseForm;$('#prev-month').onclick=()=>{calDate.setMonth(calDate.getMonth()-1);renderCalendar()};$('#next-month').onclick=()=>{calDate.setMonth(calDate.getMonth()+1);renderCalendar()};$('#this-month').onclick=()=>{calDate=new Date();selectedDay=todayISO();renderCalendar();renderDayList(selectedDay)};$('#booking-search').oninput=renderBookings;$('#booking-filter').onchange=renderBookings;$('#customer-search').oninput=renderCustomers;$('#ledger-filter').onchange=renderFinance;$$('[data-car-filter]').forEach(x=>x.onclick=()=>{carFilter=x.dataset.carFilter;$$('[data-car-filter]').forEach(b=>b.classList.toggle('active',b===x));renderFleet()});$('#export-csv').onclick=exportCSV;
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#modal-backdrop').classList.contains('hidden'))closeModal()});
function renderQuotes(){if(!$('#quotes-table'))return;const rows=(db.quotes||[]).slice().sort((a,b)=>b.created.localeCompare(a.created));$('#quotes-table').innerHTML=rows.map(q=>`<tr><td>${q.id}<span class="subtext">${dateFmt(q.created)}</span></td><td>${esc(customer(q.customerId)?.name||'')}</td><td>${esc(car(q.carId)?.name||'')}<span class="subtext">${esc(car(q.carId)?.plate||'')}</span></td><td>${dtFmt(q.start)} – ${dtFmt(q.end)}<span class="subtext">${q.days} วัน</span></td><td><b>${money(q.total)}</b></td><td><span class="status status-${q.status==='converted'?'confirmed':q.status==='cancelled'?'cancelled':'quoted'}">${({quoted:'เสนอราคาแล้ว',converted:'เปลี่ยนเป็นรายการเช่าแล้ว',expired:'หมดอายุ',cancelled:'ยกเลิก'})[q.status]||q.status}</span></td><td><button class="text-button" data-quote-print="${q.id}">พิมพ์ใบเสนอราคา</button>${q.status==='quoted'?`<button class="text-button" data-quote-convert="${q.id}">สร้างรายการเช่า</button>`:''}</td></tr>`).join('');$('#quotes-empty').classList.toggle('hidden',rows.length>0);$$('[data-quote-convert]').forEach(b=>b.onclick=()=>bookingForm('',b.dataset.quoteConvert));$$('[data-quote-print]').forEach(b=>b.onclick=()=>printQuote(b.dataset.quotePrint))}
function printQuote(id){const q=db.quotes.find(x=>x.id===id);if(!q)return;const c=customer(q.customerId),v=car(q.carId);openModal('ใบเสนอราคา',`เลขที่ ${q.id}`,`<div class="receipt"><div class="receipt-brand"><b>AB CARRENT</b><span>รถเช่านครศรีธรรมราช</span><small>โทร. 081-234-5678</small></div><h3>ใบเสนอราคา</h3><div class="receipt-info"><div><span>ลูกค้า</span><br>${esc(c?.taxName||c?.name||'')}</div><div><span>วันที่ออก</span><br>${dateFmt(q.created)}</div><div><span>รถ</span><br>${esc(v?.name||'')} · ${esc(v?.plate||'')}</div><div><span>ช่วงเวลาเช่า</span><br>${dtFmt(q.start)} – ${dtFmt(q.end)}</div><div><span>จำนวนวัน</span><br>${q.days} วัน</div><div><span>วงเงินประกัน</span><br>${money(q.insuranceCoverage)}</div></div><div class="receipt-line"><span>ค่าเช่ารถ${q.insurance?' · '+esc(q.insurance):''}</span><span>${money(q.total-(q.extraCharges||[]).reduce((s,x)=>s+Number(x.amount),0))}</span></div>${(q.extraCharges||[]).map(x=>`<div class="receipt-line"><span>${esc(x.title)}</span><span>${money(x.amount)}</span></div>`).join('')}<div class="receipt-line"><span>เงินมัดจำ</span><span>${money(q.deposit)}</span></div><div class="receipt-total"><span>ยอดเสนอ</span><span>${money(q.total)}</span></div><div class="receipt-note">ใบเสนอราคานี้ไม่ถือเป็นการยืนยันการจอง จนกว่าจะบันทึกรายการเช่า</div></div><div class="form-actions"><button class="secondary-button cancel-modal">ปิด</button><button class="primary-button" id="print-quote">พิมพ์ใบเสนอราคา</button></div>`);$('.cancel-modal').onclick=closeModal;$('#print-quote').onclick=()=>window.print()}
function quoteForm(){if(!db.cars.length||!db.customers.length)return toast('เพิ่มรถและลูกค้าก่อนออกใบเสนอราคา');openModal('ออกใบเสนอราคา','กำหนดลูกค้า รถ และช่วงเวลาเช่า',`<form id="quote-form"><div class="form-grid"><div class="field full"><label>ลูกค้า *</label><select name="customerId" required>${customerOpts()}</select></div><div class="field full"><label>รถที่ว่าง *</label><select name="carId" id="quote-car" required>${carOpts()}</select></div><div class="field"><label>รับรถ *</label><input name="start" type="datetime-local" value="${todayISO()}T09:00" required></div><div class="field"><label>คืนรถ *</label><input name="end" type="datetime-local" value="${isoOffset(1)}T09:00" required></div><div class="field"><label>มัดจำ (บาท)</label><input name="deposit" type="number" min="0" value="0"></div><div class="field"><label>ประกัน / รายละเอียด</label><input name="insurance"></div><div class="field"><label>วงเงินประกัน (บาท)</label><input name="insuranceCoverage" type="number" min="0" value="0"></div><div class="field"><label>ค่าใช้จ่ายเพิ่มเติม</label><input name="extraTitle" placeholder="ค่ารถไปส่ง"></div><div class="field"><label>จำนวนเงินเพิ่ม (บาท)</label><input name="extraAmount" type="number" min="0" value="0"></div><div class="field full"><div class="price-preview"><span id="quote-calc">คำนวณราคา</span><b id="quote-total">฿0</b></div></div></div><div class="form-actions"><button type="button" class="secondary-button cancel-modal">ยกเลิก</button><button class="primary-button">บันทึกใบเสนอราคา</button></div></form>`);$('.cancel-modal').onclick=closeModal;const f=$('#quote-form'),updateCars=()=>{const chosen=f.carId.value,available=db.cars.filter(c=>c.available&&!hasConflict(c.id,f.start.value,f.end.value));f.carId.innerHTML=available.map(c=>`<option value="${c.id}" ${c.id===chosen?'selected':''}>${esc(c.name)} · ${esc(c.plate)}</option>`).join('')||'<option value="">ไม่มีรถว่าง</option>';const d=duration(f.start.value,f.end.value),extra=Number(f.extraAmount.value)||0;$('#quote-calc').textContent=d?`ค่าเช่า ${d} วัน + ค่าใช้จ่ายเพิ่มเติม ${money(extra)}`:'กรุณาตรวจสอบช่วงเวลา';$('#quote-total').textContent=money(d*(car(f.carId.value)?.price||0)+extra)};f.start.onchange=f.end.onchange=updateCars;f.carId.onchange=f.extraAmount.oninput=updateCars;updateCars();f.onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(f)),days=duration(d.start,d.end);if(!days||!d.carId||hasConflict(d.carId,d.start,d.end))return toast('ช่วงเวลาไม่ถูกต้องหรือรถไม่ว่าง');const extraCharges=d.extraTitle&&Number(d.extraAmount)>0?[{title:d.extraTitle,amount:Number(d.extraAmount)}]:[];db.quotes.push({id:'QT-'+Date.now().toString().slice(-7),customerId:d.customerId,carId:d.carId,start:d.start,end:d.end,days,total:days*car(d.carId).price+extraCharges.reduce((s,x)=>s+x.amount,0),deposit:Number(d.deposit)||0,insurance:d.insurance||'',insuranceCoverage:Number(d.insuranceCoverage)||0,extraCharges,status:'quoted',created:todayISO()});persist();closeModal();show('quotes');toast('ออกใบเสนอราคาแล้ว')}}
let thaiGeoPromise=null;
async function thaiGeo(){if(!thaiGeoPromise)thaiGeoPromise=Promise.all(['province','district','sub_district'].map(async n=>{const r=await fetch(`https://raw.githubusercontent.com/kongvut/thai-province-data/refs/heads/master/api/latest/${n}.json`);if(!r.ok)throw new Error('โหลดข้อมูลที่อยู่ไม่สำเร็จ');return r.json()})).then(([provinces,districts,subdistricts])=>({provinces,districts,subdistricts}));return thaiGeoPromise}
function setupThaiAddress(old){const p=$('#customer-province'),d=$('#customer-district'),s=$('#customer-subdistrict'),zip=$('#customer-postal'),th=x=>x?.name?.th||'',label=x=>`${x?.prefix?.th||''}${th(x)}`;thaiGeo().then(g=>{p.innerHTML='<option value="">เลือกจังหวัด</option>'+g.provinces.map(x=>`<option>${esc(th(x))}</option>`).join('');if(old?.province){p.value=old.province;p.dispatchEvent(new Event('change'))}}).catch(()=>toast('โหลดรายชื่อจังหวัดไม่สำเร็จ ตรวจสอบอินเทอร์เน็ตแล้วลองเปิดฟอร์มใหม่'));p.onchange=async()=>{const g=await thaiGeo(),prov=g.provinces.find(x=>th(x)===p.value);d.innerHTML='<option value="">เลือกอำเภอ</option>'+g.districts.filter(x=>String(x.province_id)===String(prov?.id)).map(x=>`<option value="${esc(label(x))}" data-id="${x.id}">${esc(label(x))}</option>`).join('');d.disabled=!prov;s.innerHTML='<option value="">เลือกตำบล</option>';s.disabled=true;if(old?.district){const row=g.districts.find(x=>String(x.province_id)===String(prov?.id)&&(label(x)===old.district||th(x)===old.district));if(row){d.value=label(row);d.dispatchEvent(new Event('change'))}}};d.onchange=async()=>{const g=await thaiGeo(),districtId=d.selectedOptions[0]?.dataset.id;s.innerHTML='<option value="">เลือกตำบล</option>'+g.subdistricts.filter(x=>String(x.district_id)===String(districtId)).map(x=>`<option value="${esc(label(x))}" data-zip="${x.zip_code||''}">${esc(label(x))}</option>`).join('');s.disabled=!districtId;if(old?.subdistrict){const row=[...s.options].find(x=>x.value===old.subdistrict||x.text===old.subdistrict);if(row)s.value=row.value}};s.onchange=()=>{zip.value=s.selectedOptions[0]?.dataset.zip||zip.value}}
function readFileData(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)})}
async function openCustomerDocument(c,type){const key=type==='id'?'idDocument':'licenseDocument',data=c[key+'Data'],path=c[key+'Path'];if(data){const w=window.open();if(w)w.location.href=data;return}if(path&&onlineMode){const {data:result,error}=await supabaseClient.storage.from('customer-documents').createSignedUrl(path,60);if(error)return toast('เปิดไฟล์ไม่ได้ กรุณาตรวจ Storage policy');window.open(result.signedUrl,'_blank','noopener')}}
initializeApp();
